<?php

use PHPUnit\Framework\Attributes\DataProvider;

/**
 * Real audio files (generated by tests/fixtures/generate.sh) in each common format.
 */
final class FixturesTest extends AnalyzeTestCase
{
	public static function fixtures(): array {
		$full = array('title' => 'TestTitle', 'artist' => 'TestArtist', 'album' => 'TestAlbum', 'genre' => 'Rock');
		return array(
			'MP3 + ID3v2.3 + cover art' => array('sine-id3v23-apic.mp3', 'mp3', 'mp3', 'id3v2', $full),
			'MP3 + ID3v2.4'             => array('sine-id3v24.mp3', 'mp3', 'mp3', 'id3v2', $full),
			'FLAC'                      => array('sine.flac', 'flac', 'flac', 'vorbiscomment', $full),
			'Ogg Vorbis'                => array('sine.ogg', 'ogg', 'vorbis', 'vorbiscomment', $full),
			'MP4/AAC'                   => array('sine.m4a', 'mp4', 'mp4', 'quicktime', $full),
			// RIFF INFO has no album field; ffmpeg writes it as "product" (IPRD)
			'WAV'                       => array('sine.wav', 'wav', 'wav', 'riff', array('title' => 'TestTitle', 'artist' => 'TestArtist', 'product' => 'TestAlbum', 'genre' => 'Rock')),
			// ffmpeg only writes NAME and COMT chunks to AIFF
			'AIFF'                      => array('sine.aiff', 'aiff', 'aiff', 'riff', array('title' => 'TestTitle', 'comment' => 'A_comment')),
		);
	}

	#[DataProvider('fixtures')]
	public function testFixture(string $file, string $fileformat, string $dataformat, string $tagformat, array $expectedComments): void {
		$info = $this->analyze(self::FIXTURES.$file);

		$this->assertArrayNotHasKey('error', $info);
		$this->assertSame($fileformat, $info['fileformat']);
		$this->assertSame($dataformat, $info['audio']['dataformat']);
		$this->assertSame(22050, (int) $info['audio']['sample_rate']);
		$this->assertEqualsWithDelta(0.5, $info['playtime_seconds'], 0.1);
		$this->assertArrayHasKey($tagformat, $info['tags']);
		foreach ($expectedComments as $key => $value) {
			$this->assertSame(array($value), $info['comments'][$key] ?? null, $key);
		}
	}

	public function testUntaggedMp3(): void {
		$info = $this->analyze(self::FIXTURES.'sine.mp3');
		$this->assertArrayNotHasKey('error', $info);
		$this->assertSame('mp3', $info['fileformat']);
		$this->assertArrayNotHasKey('tags', $info);
		$this->assertEqualsWithDelta(0.5, $info['playtime_seconds'], 0.1);
	}

	public function testCoverArt(): void {
		$info = $this->analyze(self::FIXTURES.'sine-id3v23-apic.mp3');
		$picture = $info['comments']['picture'][0];
		$this->assertSame('image/png', $picture['image_mime']);
		$this->assertSame("\x89PNG", substr($picture['data'], 0, 4));
		$this->assertSame(16, $picture['image_width']);
		$this->assertSame(16, $picture['image_height']);
	}

	public function testId3v1Tag(): void {
		$tag  = 'TAG';
		$tag .= str_pad('V1 Title', 30, "\x00");
		$tag .= str_pad('V1 Artist', 30, "\x00");
		$tag .= str_pad('V1 Album', 30, "\x00");
		$tag .= '1999';
		$tag .= str_pad('V1 Comment', 28, "\x00")."\x00\x07"; // ID3v1.1 track number
		$tag .= chr(17); // Rock
		$info = $this->analyzeBytes(self::mpegAudio().$tag);

		$this->assertSame(array('V1 Title'), $info['comments']['title']);
		$this->assertSame(array('7'), array_map('strval', $info['comments']['track_number']));
		$this->assertSame(array('Rock'), $info['comments']['genre']);
	}

	public function testId3v1TagTruncatedTrackByte(): void {
		// a file that ends right before the ID3v1 genre byte
		$tag = 'TAG'.str_repeat("\x00", 124);
		$info = $this->analyzeBytes(self::mpegAudio().$tag);
		$this->assertSame('mp3', $info['fileformat']);
	}

	public static function truncatableFixtures(): array {
		$cases = array();
		foreach (array_keys(self::fixtures()) as $name) {
			$cases[$name] = array(self::fixtures()[$name][0]);
		}
		return $cases;
	}

	/**
	 * Partially uploaded files must not raise deprecations, warnings or uncaught errors.
	 */
	#[DataProvider('truncatableFixtures')]
	public function testTruncatedFixture(string $file): void {
		$data = file_get_contents(self::FIXTURES.$file);
		$step = max(1, intdiv(strlen($data), 300));
		$problems = array();
		for ($length = 0; $length < strlen($data); $length += $step) {
			$issues = self::collectIssues(function () use ($data, $length, $file) {
				$this->analyzeBytes(substr($data, 0, $length), '.'.pathinfo($file, PATHINFO_EXTENSION));
			});
			foreach ($issues as $issue) {
				$problems[$issue] = 'first seen at length '.$length;
			}
		}
		$this->assertSame(array(), $problems);
	}
}
